"""Owner-authorized practice editing, separate from immutable source questions/keys.

Choices must be meaningful in their row, and remain reusable. Label aliases are
only for equivalent wording, never for changing a formerly wrong scientific
answer into a correct one. Each run is idempotent and records a review inventory.
"""
import itertools
import json
from pathlib import Path
from native_first_five import B, C, T

ROOT=Path(__file__).resolve().parents[1]
ASSETS=ROOT/'app/src/main/assets'

def write():
    chapters={c:json.loads((ASSETS/f'content/chapter{c}.json').read_text())for c in range(1,11)}
    by_id={q['canonicalId']:q for qs in chapters.values()for q in qs}
    edits=[]
    def question(c,n):return by_id[f'g7_ch{c:02}_q{n:02}']
    def row(c,n,index,values,left=None,step=0,equivalent=True):
        q=question(c,n);s=q['steps'][step];p=s['pairs'][index]
        before=dict(p);old=p['right'];previous=p.get('choices')or s.get('choices')or []
        if equivalent:
            aliases=s.setdefault('choiceAliases',{})
            if old!=values[0]:aliases[old]=values[0]
            # Preserve old aliases through subsequent wording improvements.
            for key,value in list(aliases.items()):
                if value==old:aliases[key]=values[0]
        p['right']=values[0];p['choices']=values
        if left is not None:p['left']=left
        if before!=p:edits.append(dict(question=q['canonicalId'],row=index,old=before,new=p))
    def note(c,n,text,uses_print=False):
        q=question(c,n);q['sourceReviewNote']=text;q['practiceUsesPrintedKey']=uses_print

    # Shared banks, true/false, classifications and row-specific lists are reusable.
    # This flag also keeps data exports consistent with the shared Android editor.
